package com.franco.desco.adapter.in.web.production;import com.franco.desco.application.production.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.production.ProductionModels;import org.springframework.stereotype.Component;import java.time.LocalDate;
@Component public class ProductionWebMapper{public ProductionCommands.ListProduction list(int p,int t,String estado,Long zona,Long predio,Long socio,Long asociacion,Integer variedad,String origen,LocalDate desde,LocalDate hasta){return new ProductionCommands.ListProduction(new PageRequest<>(p,t,new ProductionCommands.Filter(estado,zona,predio,socio,asociacion,variedad,origen,desde,hasta),null,null));}public ProductionResponses.Summary response(ProductionModels.Summary x){return new ProductionResponses.Summary(x.disponibilidadProduccionId(),x.fechaEstimacion(),x.disponibleDesde(),x.disponibleHasta(),x.cantidadEstimadaKg(),x.estadoEstimacion(),x.observacion(),x.parcelaCultivoId(),x.variedadPaltaId(),x.variedad(),x.parcelaId(),x.parcelaNombre(),x.predioId(),x.predioCodigo(),x.predioNombre(),x.zonaProductivaId(),x.zonaProductiva(),x.socioId(),x.socioNombre(),x.asociacionId(),x.asociacionNombre(),x.visitaTecnicaId(),x.origenEstimacion());}public ProductionResponses.Detail response(ProductionModels.Detail x){return new ProductionResponses.Detail(response(x.produccion()),x.estadoCultivo(),x.visitaFechaInicio(),x.visitaEstado(),x.archivos().stream().map(f->new ProductionResponses.File(f.archivoId(),f.nombreOriginal(),f.mimeType(),f.secureUrl(),f.categoria(),f.tipoEvidencia(),f.origenCaptura(),f.descripcion(),f.fechaCaptura(),f.fechaCarga())).toList());}}
